#include "multi_lfo.h"

namespace ekphore::dsp {

float MultiLfo::lookup(const std::array<std::uint32_t, 4096> &table,
        double position) noexcept {
    const double scaled = position * 4096.;
    const auto index = static_cast<std::int32_t>(scaled);
    const float a = static_cast<float>(scaled - index) + 1.F;
    const float b = a - 1.F, c = b - 1.F, d = c - 1.F;
    const auto read = [&](int offset) {
        return std::bit_cast<float>(
                table[static_cast<std::uint32_t>(index + offset) & 4095U]);
    };
    float v0 = mul(read(0), a);
    float v1 = mul(read(1), a);
    float v2 = mul(read(2), a);
    v1 = mul(b, v1);
    v2 = mul(b, v2);
    v0 = mul(c, v0);
    v2 = mul(c, v2);
    float v3 = mul(b, -read(-1));
    v3 = mul(c, v3);
    v3 = std::fma(v3, d, v2);
    v3 = mul(v3, std::bit_cast<float>(0x3e2aaaabU));
    v0 = mul(d, v0 - v1);
    v0 = mul(v0, .5F);
    return v0 + v3;
}

void MultiLfo::generate_impl(std::span<float> output,
        std::span<const float> frequency_controls, float inverse_control_rate,
        int fractional_frames) noexcept {
    std::size_t tick = 0;
    for (auto &value : output) {
        if (!frequency_controls.empty())
            step = frequency_step(
                    frequency_controls[tick++], inverse_control_rate);
        value = mul(lookup(lfo_rom::sine, phase), -weights[0]);
        value = std::fma(-lookup(lfo_rom::saw, phase * 2.), weights[1], value);
        value = std::fma(
                lookup(lfo_rom::triangle, phase + .75), weights[2], value);
        double rectangle;
        if (std::abs(pulse_width - .5F) < .01F) {
            rectangle = lookup(lfo_rom::rectangle, phase);
        } else {
            const float difference =
                    lookup(lfo_rom::saw, phase) -
                    lookup(lfo_rom::saw, 1. - pulse_width + phase);
            rectangle = static_cast<double>(difference) -
                        std::fma(static_cast<double>(pulse_width), -2., 1.);
        }
        value = std::fma(-static_cast<float>(rectangle), weights[3], value);
        value = std::fma(random_value, weights[4], value);
        phase += step;
        if (phase >= random_threshold) {
            random_state = random_state * 0x0bb38435U + 0x3619636bU;
            random_value = std::bit_cast<float>(
                                   (random_state & 0x7fffffU) | 0x40000000U) -
                           3.F;
            random_threshold = 1.5 - random_threshold;
        }
        if (phase > 1.)
            phase -= 1.;
    }
    if (normalize) {
        float sum = std::abs(weights[0]) + std::abs(weights[1]);
        for (unsigned i = 2; i < 5; ++i)
            sum += std::abs(weights[i]);
        const float factor = 1.F / std::max(1.F, sum);
        for (auto &value : output)
            value = mul(value, factor);
    }
    const int fading =
            std::min(fade_remaining, static_cast<int>(output.size()));
    for (int i = 0; i < fading; ++i) {
        output[i] = mul(fade - .3F, output[i]);
        fade = std::clamp(mul(fade_factor, fade), fade_extended ? .3F : 0.F,
                fade_extended ? 1.3F : 1.F);
    }
    fade_remaining -= fading;
    phase = std::fma(
            static_cast<double>(fractional_frames) * (-1. / 32.), step, phase);
    if (phase < 0.)
        phase += 1.;
}

} // namespace ekphore::dsp

